// Precomputed ESC/POS raster bitmap commands for thermal printing of official MEZBAAN logo
export const ESCPOS_LOGO_58_B64 = "";
export const ESCPOS_LOGO_80_B64 = "";

function base64ToBytes(b64: string): Uint8Array {
  const binary = atob(b64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  return bytes;
}

export const ESCPOS_LOGO_58 = base64ToBytes(ESCPOS_LOGO_58_B64);
export const ESCPOS_LOGO_80 = base64ToBytes(ESCPOS_LOGO_80_B64);
